import assert from 'node:assert/strict';
import { monthlyReport } from './impl.ts';
assert.deepEqual(monthlyReport({ month: '2026-03', timezone: 'America/New_York' }, [
  { id: 'sale-in', type: 'sale', amountCents: 10000, at: '2026-03-01T05:00:00Z' },
  { id: 'sale-out', type: 'sale', amountCents: 99999, at: '2026-03-01T04:59:59Z' },
  { id: 'fee-in', type: 'fee', amountCents: 300, at: '2026-03-15T12:00:00Z' },
  { id: 'refund-in', type: 'refund', amountCents: 2000, at: '2026-03-20T12:00:00Z', saleAt: '2026-02-10T12:00:00Z' },
  { id: 'refund-out', type: 'refund', amountCents: 50000, at: '2026-04-01T04:00:00Z', saleAt: '2026-03-10T12:00:00Z' },
]), { grossCents: 10000, feesCents: 300, refundsCents: 2000, netCents: 7700 });
assert.deepEqual(monthlyReport({ month: '2026-03', timezone: 'UTC' }, []), { grossCents: 0, feesCents: 0, refundsCents: 0, netCents: 0 });
console.log('monthly report assertions passed');
EOF
